// widowsguide.org: the email sign-up.
// The form on every page posts here. This adds the address to MailerLite and
// sends her to /thanks/. Generated by 09_site/build_site.py; edit there.
//
// Netlify > Site configuration > Environment variables:
//   MAILERLITE_API_KEY    required. MailerLite > Integrations > Developer API.
//   MAILERLITE_GROUP_ID   optional. The group to put her in.
//
// Nothing here is secret, so it is safe in version control.

const THANKS = "/thanks/";
const FAILED = "/thanks/?ok=0";
const API = "https://connect.mailerlite.com/api/subscribers";
const LOOKS_LIKE_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const sendHer = (to) =>
  new Response(null, { status: 303, headers: { Location: to, "Cache-Control": "no-store" } });

export default async (request) => {
  if (request.method !== "POST") return sendHer(THANKS);

  let form;
  try {
    form = new URLSearchParams(await request.text());
  } catch {
    return sendHer(FAILED);
  }

  // Only a robot fills the honeypot in. Thank it and do nothing.
  if ((form.get("bot-field") || "").trim()) return sendHer(THANKS);

  const email = (form.get("email") || "").trim().toLowerCase();
  if (email.length > 254 || !LOOKS_LIKE_EMAIL.test(email)) return sendHer(FAILED);

  const key = process.env.MAILERLITE_API_KEY;
  if (!key) {
    console.error("MAILERLITE_API_KEY is not set in this site's environment variables");
    return sendHer(FAILED);
  }

  // status "active" puts her straight on the list, with no confirmation email.
  const body = { email, status: "active" };
  const group = (process.env.MAILERLITE_GROUP_ID || "").trim();
  if (group) body.groups = [group];
  const interest = (form.get("interest") || "").trim().slice(0, 120);
  if (interest) body.fields = { interest };

  const post = (payload) =>
    fetch(API, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify(payload),
    });

  try {
    let res = await post(body);
    // MailerLite refuses a custom field it doesn't have yet. Her address matters
    // more than the note of where she signed up, so try again without it.
    if (res.status === 422 && body.fields) {
      console.warn('MailerLite rejected the "interest" field; subscribing without it');
      delete body.fields;
      res = await post(body);
    }
    if (!res.ok) {
      console.error("MailerLite replied", res.status, (await res.text()).slice(0, 500));
      return sendHer(FAILED);
    }
  } catch (err) {
    console.error("Could not reach MailerLite", err);
    return sendHer(FAILED);
  }

  return sendHer(THANKS);
};

export const config = { path: "/api/subscribe" };
